# Check flood fill from 5s more carefully
def flood_fill_from_5(grid):
    """Find all cells reachable from any 5."""
    h, w = len(grid), len(grid[0])
    positions_5 = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                positions_5.add((r, c))

    visited = [[False]*w for _ in range(h)]
    queue = []
    for (r, c) in positions_5:
        visited[r][c] = True
        queue.append((r, c))

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                if grid[nr][nc] != 5:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    return [(r, c) for r in range(h) for c in range(w) if visited[r][c]]

