def fill_between_5s_horizontal(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        # Find all columns with 5 in this row
        five_cols = [c for c in range(w) if grid[r][c] == 5]

        if not five_cols:
            continue

        # Fill between consecutive 5s
        for i in range(len(five_cols) - 1):
            start_col = five_cols[i] + 1
